package io.github.diodeme.ji.provider.openai;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.github.diodeme.ji.ai.Content;
import io.github.diodeme.ji.ai.Message;
import io.github.diodeme.ji.ai.ModelProvider;
import io.github.diodeme.ji.ai.ModelRequest;
import io.github.diodeme.ji.ai.ModelStreamEvent;
import io.github.diodeme.ji.ai.ProviderFailure;
import io.github.diodeme.ji.ai.Usage;
import io.github.diodeme.ji.error.ErrorCode;
import io.github.diodeme.ji.error.JiError;
import io.github.diodeme.ji.error.JiException;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.OptionalLong;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Flow;
import java.util.concurrent.SubmissionPublisher;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Supplier;

/** Minimal OpenAI-compatible Chat Completions SSE adapter. */
public final class OpenAiProvider implements ModelProvider {
    private static final Duration CONNECT_TIMEOUT = Duration.ofSeconds(15);
    private final URI endpoint;
    private final Supplier<char[]> credentialResolver;
    private final Map<String, String> headers;
    private final HttpClient client;
    private final ObjectMapper mapper = new ObjectMapper();
    private final AtomicBoolean closed = new AtomicBoolean();

    private OpenAiProvider(Builder builder) {
        endpoint = normalizeEndpoint(builder.baseUrl);
        credentialResolver = builder.credentialResolver;
        headers = Map.copyOf(builder.headers);
        client = HttpClient.newBuilder().connectTimeout(CONNECT_TIMEOUT).followRedirects(HttpClient.Redirect.NEVER).build();
    }

    public static Builder builder() {
        return new Builder();
    }

    public URI endpoint() {
        return endpoint;
    }

    @Override
    public Flow.Publisher<ModelStreamEvent> stream(ModelRequest request) {
        if (closed.get()) throw new JiException(new JiError(ErrorCode.PROVIDER_CLOSED,
                Map.of("provider", "openai"), Optional.empty(), Optional.empty(), OptionalLong.empty()));
        var publisher = new SubmissionPublisher<ModelStreamEvent>();
        var terminal = new AtomicBoolean();
        char[] credential = credentialResolver.get();
        try {
            HttpRequest.Builder http = HttpRequest.newBuilder(endpoint)
                    .header("Content-Type", "application/json")
                    .header("Accept", "text/event-stream")
                    .POST(HttpRequest.BodyPublishers.ofString(encodeRequest(request), StandardCharsets.UTF_8));
            if (credential.length > 0) http.header("Authorization", "Bearer " + new String(credential));
            headers.forEach(http::header);
            CompletableFuture<HttpResponse<Flow.Publisher<List<java.nio.ByteBuffer>>>> response = client.sendAsync(
                    http.build(), HttpResponse.BodyHandlers.ofPublisher());
            var bodySubscription = new java.util.concurrent.atomic.AtomicReference<Flow.Subscription>();
            request.cancellation().cancellation().thenRun(() -> {
                response.cancel(true);
                Flow.Subscription subscription = bodySubscription.get();
                if (subscription != null) subscription.cancel();
                emitCompleted(publisher, terminal, ModelStreamEvent.StopReason.ABORTED, Usage.ZERO);
            });
            response.whenComplete((value, failure) -> {
                java.util.Arrays.fill(credential, '\0');
                if (failure != null) {
                    emitFailure(publisher, request, terminal, failure);
                    return;
                }
                if (value.statusCode() / 100 != 2) {
                    if (terminal.compareAndSet(false, true)) {
                        publisher.submit(new ModelStreamEvent.Failed(
                                mapStatus(value.statusCode(), value.headers().firstValue("retry-after"))));
                        publisher.close();
                    }
                    return;
                }
                value.body().subscribe(new SseSubscriber(publisher, request, terminal, bodySubscription));
            });
        } catch (RuntimeException exception) {
            java.util.Arrays.fill(credential, '\0');
            emitFailure(publisher, request, terminal, exception);
        }
        return publisher;
    }

    @Override
    public void close() {
        closed.set(true);
    }

    private String encodeRequest(ModelRequest request) {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("model", request.model().model());
        body.put("stream", true);
        body.put("stream_options", Map.of("include_usage", true));
        var messages = new ArrayList<Map<String, Object>>();
        if (!request.systemPrompt().isBlank()) messages.add(Map.of("role", "system", "content", request.systemPrompt()));
        for (Message message : request.messages()) {
            if (message.role() == Message.Role.USER) messages.add(Map.of("role", "user", "content", message.text()));
            else if (message.role() == Message.Role.ASSISTANT) {
                var entry = new LinkedHashMap<String, Object>();
                entry.put("role", "assistant");
                entry.put("content", message.text().isEmpty() ? null : message.text());
                List<Map<String, Object>> calls = message.content().stream().filter(Content.ToolCall.class::isInstance)
                        .map(Content.ToolCall.class::cast).map(call -> Map.<String, Object>of(
                                "id", call.id(), "type", "function", "function", Map.of(
                                        "name", call.name(), "arguments", encode(call.arguments())))).toList();
                if (!calls.isEmpty()) entry.put("tool_calls", calls);
                messages.add(entry);
            } else {
                messages.add(Map.of("role", "tool", "content", message.text(), "tool_call_id", message.toolCallId().orElseThrow()));
            }
        }
        body.put("messages", messages);
        if (!request.tools().isEmpty()) {
            body.put("tools", request.tools().stream().map(tool -> Map.of("type", "function", "function", Map.of(
                    "name", tool.name(), "description", tool.description(), "parameters", tool.inputSchema()))).toList());
        }
        return encode(body);
    }

    private String encode(Object value) {
        try { return mapper.writeValueAsString(value); }
        catch (JsonProcessingException exception) { throw new IllegalArgumentException("request is not JSON serializable", exception); }
    }

    private static void emitCompleted(SubmissionPublisher<ModelStreamEvent> publisher, AtomicBoolean terminal,
                                      ModelStreamEvent.StopReason reason, Usage usage) {
        if (!terminal.compareAndSet(false, true)) return;
        publisher.submit(new ModelStreamEvent.Completed(usage, reason));
        publisher.close();
    }

    private void emitFailure(SubmissionPublisher<ModelStreamEvent> publisher, ModelRequest request,
                             AtomicBoolean terminal, Throwable failure) {
        if (request.cancellation().isCancellationRequested()) {
            emitCompleted(publisher, terminal, ModelStreamEvent.StopReason.ABORTED, Usage.ZERO);
            return;
        }
        if (!terminal.compareAndSet(false, true)) return;
        publisher.submit(new ModelStreamEvent.Failed(new ProviderFailure("provider.timeout",
                Map.of("provider", request.model().provider(), "phase", "stream"), Optional.empty())));
        publisher.close();
    }

    private ProviderFailure mapStatus(int status, Optional<String> retryAfter) {
        if (status == 429) return new ProviderFailure("provider.rate_limited", Map.of("provider", "openai"),
                retryAfter.flatMap(OpenAiProvider::duration));
        return new ProviderFailure("internal.unexpected", Map.of(), Optional.empty());
    }

    private static Optional<Duration> duration(String value) {
        try { return Optional.of(Duration.ofSeconds(Long.parseLong(value))); }
        catch (NumberFormatException ignored) { return Optional.empty(); }
    }

    public static URI normalizeEndpoint(String baseUrl) {
        if (baseUrl == null || baseUrl.isBlank()) throw new IllegalArgumentException("baseUrl is required");
        String normalized = baseUrl.replaceAll("/+$", "");
        if (!normalized.endsWith("/v1")) normalized += "/v1";
        return URI.create(normalized + "/chat/completions");
    }

    public static final class Builder {
        private String baseUrl;
        private Supplier<char[]> credentialResolver = () -> new char[0];
        private final Map<String, String> headers = new LinkedHashMap<>();
        public Builder baseUrl(String value) { baseUrl = value; return this; }
        public Builder credentialResolver(Supplier<char[]> value) { credentialResolver = value; return this; }
        public Builder header(String name, String value) { headers.put(name, value); return this; }
        public OpenAiProvider build() { return new OpenAiProvider(this); }
    }

    private final class SseSubscriber implements Flow.Subscriber<List<java.nio.ByteBuffer>> {
        private final SubmissionPublisher<ModelStreamEvent> output;
        private final ModelRequest request;
        private final AtomicBoolean terminal;
        private final java.util.concurrent.atomic.AtomicReference<Flow.Subscription> subscriptionOwner;
        private final AtomicBoolean started = new AtomicBoolean();
        private final ByteArrayOutputStream undecoded = new ByteArrayOutputStream();
        private final Map<Integer, MutableToolCall> calls = new LinkedHashMap<>();
        private Flow.Subscription subscription;
        private Usage usage = Usage.ZERO;
        private ModelStreamEvent.StopReason finishReason;
        SseSubscriber(SubmissionPublisher<ModelStreamEvent> output, ModelRequest request, AtomicBoolean terminal,
                      java.util.concurrent.atomic.AtomicReference<Flow.Subscription> subscriptionOwner) {
            this.output = output;
            this.request = request;
            this.terminal = terminal;
            this.subscriptionOwner = subscriptionOwner;
        }
        @Override public void onSubscribe(Flow.Subscription value) {
            subscription = value;
            subscriptionOwner.set(value);
            if (terminal.get()) value.cancel();
            else value.request(1);
        }
        @Override public void onNext(List<java.nio.ByteBuffer> chunks) {
            if (terminal.get()) return;
            if (request.cancellation().isCancellationRequested()) { subscription.cancel(); complete(ModelStreamEvent.StopReason.ABORTED); return; }
            for (java.nio.ByteBuffer chunk : chunks) {
                byte[] bytes = new byte[chunk.remaining()];
                chunk.get(bytes);
                undecoded.writeBytes(bytes);
            }
            drainLines();
            subscription.request(1);
        }
        @Override public void onError(Throwable throwable) { emitFailure(output, request, terminal, throwable); }
        @Override public void onComplete() {
            if (terminal.get()) return;
            drainRemaining();
            if (!terminal.get()) complete(finishReason == null
                    ? (calls.isEmpty() ? ModelStreamEvent.StopReason.STOP : ModelStreamEvent.StopReason.TOOL_USE)
                    : finishReason);
        }
        private void drainLines() {
            byte[] bytes = undecoded.toByteArray();
            int consumed = 0;
            for (int index = 0; index < bytes.length; index++) {
                if (bytes[index] != '\n') continue;
                String line = new String(bytes, consumed, index - consumed, StandardCharsets.UTF_8).stripTrailing();
                consumed = index + 1;
                if (line.startsWith("data:")) process(line.substring(5).trim());
            }
            if (consumed > 0) {
                undecoded.reset();
                undecoded.write(bytes, consumed, bytes.length - consumed);
            }
        }
        private void drainRemaining() {
            if (undecoded.size() == 0) return;
            String line = undecoded.toString(StandardCharsets.UTF_8).stripTrailing();
            undecoded.reset();
            if (line.startsWith("data:")) process(line.substring(5).trim());
        }
        private void process(String data) {
            if ("[DONE]".equals(data)) { complete(calls.isEmpty() ? ModelStreamEvent.StopReason.STOP : ModelStreamEvent.StopReason.TOOL_USE); return; }
            try {
                JsonNode root = mapper.readTree(data);
                if (root.hasNonNull("id") && started.compareAndSet(false, true)) {
                    output.submit(new ModelStreamEvent.Started(root.path("id").asText()));
                }
                JsonNode usageNode = root.path("usage");
                if (!usageNode.isMissingNode() && !usageNode.isNull()) usage = new Usage(
                        usageNode.path("prompt_tokens").asLong(), usageNode.path("completion_tokens").asLong(), 0, 0, 0);
                JsonNode choice = root.path("choices").path(0);
                JsonNode delta = choice.path("delta");
                if (delta.hasNonNull("content") && !delta.path("content").asText().isEmpty()) {
                    output.submit(new ModelStreamEvent.TextDelta(delta.path("content").asText()));
                }
                for (JsonNode call : delta.path("tool_calls")) {
                    int index = call.path("index").asInt();
                    MutableToolCall target = calls.computeIfAbsent(index, ignored -> new MutableToolCall());
                    if (call.hasNonNull("id")) target.id = call.path("id").asText();
                    if (call.path("function").hasNonNull("name")) target.name = call.path("function").path("name").asText();
                    if (call.path("function").hasNonNull("arguments")) target.arguments.append(call.path("function").path("arguments").asText());
                }
                if (choice.hasNonNull("finish_reason")) finishReason = "tool_calls".equals(choice.path("finish_reason").asText())
                        ? ModelStreamEvent.StopReason.TOOL_USE : ModelStreamEvent.StopReason.STOP;
            } catch (IOException exception) {
                if (terminal.compareAndSet(false, true)) {
                    output.submit(new ModelStreamEvent.Failed(
                            new ProviderFailure("internal.unexpected", Map.of(), Optional.empty())));
                    output.close();
                }
            }
        }
        private void complete(ModelStreamEvent.StopReason reason) {
            if (!terminal.compareAndSet(false, true)) return;
            for (MutableToolCall call : calls.values()) output.submit(new ModelStreamEvent.ToolCallReady(call.build()));
            output.submit(new ModelStreamEvent.Completed(usage, reason));
            output.close();
        }
    }

    private final class MutableToolCall {
        private String id = "";
        private String name = "";
        private final StringBuilder arguments = new StringBuilder();
        private Content.ToolCall build() {
            try {
                @SuppressWarnings("unchecked") Map<String, Object> values = mapper.readValue(arguments.toString(), Map.class);
                return new Content.ToolCall(id, name, values);
            } catch (JsonProcessingException exception) {
                throw new IllegalArgumentException("malformed tool arguments", exception);
            }
        }
    }
}

